begin;
alter table public.hh_entries add column if not exists buyer_id uuid references auth.users on delete set null;
create or replace function public.hh_entry_change(f uuid,i uuid,action text) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid()) then raise exception 'Non autorizzato'; end if; if action='toggle' then update public.hh_entries set done=not done,completed_at=case when done then null else now() end,buyer_id=case when done or kind<>'shopping' then null else auth.uid() end where fid=f and id=i; elsif action='delete' then delete from public.hh_entries where fid=f and id=i; else raise exception 'Azione non valida'; end if; end $$;
create table if not exists public.hh_challenge_managers(fid uuid,uid uuid,primary key(fid,uid),foreign key(fid,uid) references public.hh_memberships(fid,uid) on delete cascade);
create table if not exists public.hh_challenges(id uuid primary key default gen_random_uuid(),fid uuid not null references public.hh_families on delete cascade, uid uuid not null, title text not null check(length(trim(title)) between 1 and 200), due date, points integer not null check(points between 0 and 100000), status text not null default 'assigned' check(status in ('assigned','submitted','approved')), approved_at timestamptz, bonus integer not null default 0 check(bonus between 0 and 100000), money numeric(10,2) not null default 0 check(money>=0), prize text not null default '', note text not null default '', delivered boolean not null default false, reviewer uuid);
alter table public.hh_challenge_managers enable row level security;
alter table public.hh_challenges enable row level security;
revoke all on public.hh_challenge_managers,public.hh_challenges from public,anon,authenticated;
create or replace function public.hh_challenge_manager(f uuid) returns boolean language sql security definer set search_path='' as $$ select exists(select 1 from public.hh_memberships m where m.fid=f and m.uid=auth.uid() and (m.role='admin' or (m.role='adult' and exists(select 1 from public.hh_challenge_managers g where g.fid=f and g.uid=m.uid)))) $$;
create or replace function public.hh_challenge_grant(f uuid,u uuid,onoff boolean) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.hh_memberships where fid=f and uid=auth.uid() and role='admin') or not exists(select 1 from public.hh_memberships where fid=f and uid=u and role='adult') then raise exception 'Non autorizzato'; end if; if onoff then insert into public.hh_challenge_managers values(f,u) on conflict do nothing; else delete from public.hh_challenge_managers where fid=f and uid=u; end if; end $$;
create or replace function public.hh_challenge_list(f uuid) returns jsonb language sql security definer set search_path='' as $$ select case when exists(select 1 from public.hh_memberships where fid=f and uid=auth.uid()) then jsonb_build_object('manager',public.hh_challenge_manager(f),'managers',coalesce((select jsonb_agg(uid) from public.hh_challenge_managers where fid=f),'[]'::jsonb),'rows',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from public.hh_challenges c where c.fid=f),'[]'::jsonb)) else null end $$;
create or replace function public.hh_challenge_add(f uuid,u uuid,t text,d date,p integer) returns void language plpgsql security definer set search_path='' as $$ begin if not public.hh_challenge_manager(f) or not exists(select 1 from public.hh_memberships where fid=f and uid=u) then raise exception 'Non autorizzato'; end if; insert into public.hh_challenges(fid,uid,title,due,points) values(f,u,trim(t),d,p); end $$;
create or replace function public.hh_challenge_action(f uuid,i uuid,op text,b integer default 0,m numeric default 0,p text default '',n text default '') returns void language plpgsql security definer set search_path='' as $$ declare r public.hh_challenges; manager boolean; begin select * into r from public.hh_challenges where fid=f and id=i for update; if not found or not exists(select 1 from public.hh_memberships where fid=f and uid=auth.uid()) then raise exception 'Non autorizzato'; end if; manager:=public.hh_challenge_manager(f); if op='submit' and r.status='assigned' and r.uid=auth.uid() then update public.hh_challenges set status='submitted' where id=i; elsif op='approve' and manager and r.status='submitted' then update public.hh_challenges set status='approved',approved_at=now(),bonus=b,money=m,prize=left(p,500),note=left(n,500),reviewer=auth.uid() where id=i; elsif op='return' and manager and r.status='submitted' then update public.hh_challenges set status='assigned' where id=i; elsif op='deliver' and manager and r.status='approved' then update public.hh_challenges set delivered=true where id=i; else raise exception 'Operazione non consentita'; end if; end $$;
revoke all on function public.hh_challenge_manager(uuid),public.hh_challenge_grant(uuid,uuid,boolean),public.hh_challenge_list(uuid),public.hh_challenge_add(uuid,uuid,text,date,integer),public.hh_challenge_action(uuid,uuid,text,integer,numeric,text,text) from public,anon,authenticated;
grant execute on function public.hh_challenge_manager(uuid),public.hh_challenge_grant(uuid,uuid,boolean),public.hh_challenge_list(uuid),public.hh_challenge_add(uuid,uuid,text,date,integer),public.hh_challenge_action(uuid,uuid,text,integer,numeric,text,text) to authenticated;
commit;
